     9	    private static final String RESERVED = "reserved";
    10	
    11	    private String guest;
    12	
    13	    // guests
    14	
    15	    public String guestType() {
    16	        return guest;
    17	    }
    18	
    19	    public void receive(String aGuestType) {
    20	        // Room Occupied
    21	        if (guest != null || RESERVED.equals(guest)) {
    22	            throw new RuntimeException(Room.roomIsNotEmptyErrorDescription());
    23	        } else {
    24	            guest = aGuestType;
    25	        }
    26	    }
    27	
    28	    public void receiveWithReservation(String aGuestType) {
    29	        // Room Reserved
    30	        if (RESERVED.equals(guest)) {
    31	            guest = aGuestType;
    32	        } else {
    33	            throw new RuntimeException(Room.roomIsNotReservedErrorDescription());
    34	        }
    35	    }
    36	
    37	    public void reserve() {
    38	        // Room Occupied
    39	        if (guest != null || RESERVED.equals(guest)) {
    40	            throw new RuntimeException(Room.roomIsNotEmptyErrorDescription());
    41	        } else {
    42	            guest = RESERVED;
    43	        }
    44	    }
    45	
    46	    // testing
    47	
    48	    public boolean isAvailable() {
    49	        return guest == null;
    50	    }
    51	
    52	    public boolean isOccupied() {
    53	        return guest != null || RESERVED.equals(guest);
    54	    }
    55	
    56	    public boolean isReserved() {
    57	        return RESERVED.equals(guest);
    58	    }
    59	
    60	    // accounting
    61	
    62	    public Integer profitUsingIfAbsentGuestType(HashMap<String, Integer> aPriceList, Supplier<Integer> unknownGuestTypeBlock) {
    63	        // Room Available
    64	        if (guest == null) {
    65	            return 0;
    66	        }
    67	
    68	        // Room Reserved
    69	        if (RESERVED.equals(guest)) {
    70	            return Collections.min(aPriceList.values()) / 2;
    71	        }
    72	
    73	        // Room Occupied
    74	        if (guest != null || RESERVED.equals(guest)) {
    75	            if (aPriceList.containsKey(guest)) {
    76	                return aPriceList.get(guest);
    77	            } else {
    78	                return unknownGuestTypeBlock.get();
    79	            }
    80	        }
    81	
    82	        return null;
    83	    }
    84	
    85	    public Integer lossUsingIfAbsentGuestType(HashMap<String, Integer> aPriceList, Supplier<Integer> unknownGuestTypeBlock) {
    86	        // Not implemented yet: in the Smalltalk original this message does not exist in Room
    87	        // (sending it raises MessageNotUnderstood). Java needs the method to compile the tests.
    88	        throw new UnsupportedOperationException("Room does not understand lossUsingIfAbsentGuestType");
    89	    }
