package simshotels;

import java.util.HashMap;
import java.util.function.Supplier;

class OccupiedRoomState extends RoomState {

    private final String guestType;

    OccupiedRoomState(String aGuestType) {
        guestType = aGuestType;
    }

    // testing

    @Override
    boolean isOccupied() {
        return true;
    }

    // accounting

    @Override
